package com.indexer.ws;

import javax.websocket.*;
import javax.websocket.server.ServerEndpoint;
import javax.websocket.server.HandshakeRequest;
import javax.websocket.server.ServerEndpointConfig;
import java.io.IOException;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.Collections;
import java.security.Principal;

@ServerEndpoint(value = "/index/ws", configurator = SearchIndexEndpoint.AuthConfigurator.class)
public class SearchIndexEndpoint {

    private static final ConcurrentHashMap<String, Session> activeSessions = new ConcurrentHashMap<>();
    private static final AtomicBoolean shuttingDown = new AtomicBoolean(false);
    private static final AtomicReference<String> shutdownInitiator = new AtomicReference<>(null);
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);
    private static final long GRACE_PERIOD_MS = 30000;
    private static final Set<String> ALLOWED_ORIGINS = Collections.unmodifiableSet(
        ConcurrentHashMap.newKeySet() {{
            add("https://search.internal.corp");
            add("https://admin.internal.corp");
            add("https://indexer.internal.corp");
        }}
    );

    public static class AuthConfigurator extends ServerEndpointConfig.Configurator {
        @Override
        public void modifyHandshake(ServerEndpointConfig sec, HandshakeRequest request, HandshakeResponse response) {
            Map<String, List<String>> headers = request.getHeaders();
            List<String> originHeaders = headers.get("origin");
            String sessionToken = extractSessionToken(request);
            Principal userPrincipal = request.getUserPrincipal();

            sec.getUserProperties().put("origin", originHeaders != null ? originHeaders.get(0) : "unknown");
            sec.getUserProperties().put("sessionToken", sessionToken);
            sec.getUserProperties().put("authenticated", userPrincipal != null);
            sec.getUserProperties().put("principalName", userPrincipal != null ? userPrincipal.getName() : "anonymous");
        }

        private String extractSessionToken(HandshakeRequest request) {
            Map<String, List<String>> headers = request.getHeaders();
            List<String> authHeaders = headers.get("authorization");
            if (authHeaders != null && !authHeaders.isEmpty()) {
                String auth = authHeaders.get(0);
                if (auth.startsWith("Bearer ")) {
                    return auth.substring(7);
                }
            }
            return null;
        }
    }

    @OnOpen
    public void onOpen(Session session, EndpointConfig config) throws IOException {
        Map<String, Object> props = config.getUserProperties();
        String origin = (String) props.get("origin");
        Boolean authenticated = (Boolean) props.get("authenticated");
        String principalName = (String) props.get("principalName");
        String sessionToken = (String) props.get("sessionToken");

        if (!validateConnection(origin, authenticated, sessionToken, session)) {
            return;
        }

        if (shuttingDown.get()) {
            session.close(new CloseReason(CloseReason.CloseCodes.SERVICE_RESTART, "Service shutting down"));
            return;
        }

        activeSessions.put(session.getId(), session);
        session.getUserProperties().put("role", principalName);
        session.getUserProperties().put("connectedAt", System.currentTimeMillis());
    }

    private boolean validateConnection(String origin, Boolean authenticated, String sessionToken, Session session) throws IOException {
        if (shuttingDown.get()) {
            session.close(new CloseReason(CloseReason.CloseCodes.SERVICE_RESTART, "Service shutting down"));
            return false;
        }

        if (!ALLOWED_ORIGINS.contains(origin)) {
            session.close(new CloseReason(CloseReason.CloseCodes.VIOLATED_POLICY, "Origin not allowed"));
            return false;
        }

        if (!authenticated) {
            session.close(new CloseReason(CloseReason.CloseCodes.VIOLATED_POLICY, "Authentication required"));
            return false;
        }

        return true;
    }

    @OnMessage
    public void onMessage(String message, Session session) throws IOException {
        if (shuttingDown.get()) {
            session.getBasicRemote().sendText("{\"error\": \"Service shutting down, read-only mode\"}");
            return;
        }

        IndexCommand cmd = IndexCommand.parse(message);
        if (cmd == null) {
            session.getBasicRemote().sendText("{\"error\": \"Invalid command\"}");
            return;
        }

        switch (cmd.getType()) {
            case "reindex":
                handleReindex(cmd, session);
                break;
            case "search":
                handleSearch(cmd, session);
                break;
            case "shutdown":
                handleShutdown(cmd, session);
                break;
            default:
                session.getBasicRemote().sendText("{\"error\": \"Unknown command\"}");
        }
    }

    private void handleReindex(IndexCommand cmd, Session session) throws IOException {
        String role = (String) session.getUserProperties().get("role");
        if (!"admin".equals(role) && !"indexer".equals(role)) {
            session.getBasicRemote().sendText("{\"error\": \"Insufficient privileges\"}");
            return;
        }
        String sanitizedTarget = cmd.getTarget().replaceAll("[^a-zA-Z0-9_-]", "");
        session.getBasicRemote().sendText("{\"status\": \"reindex_started\", \"collection\": \"" + sanitizedTarget + "\"}");
    }

    private void handleSearch(IndexCommand cmd, Session session) throws IOException {
        String sanitizedQuery = cmd.getTarget().replaceAll("[^a-zA-Z0-9_ -]", "");
        session.getBasicRemote().sendText("{\"results\": [], \"query\": \"" + sanitizedQuery + "\"}");
    }

    private void handleShutdown(IndexCommand cmd, Session session) throws IOException {
        String role = (String) session.getUserProperties().get("role");
        if (!"admin".equals(role)) {
            session.getBasicRemote().sendText("{\"error\": \"Admin only\"}");
            return;
        }
        initiateGracefulShutdown(session.getId());
        session.getBasicRemote().sendText("{\"status\": \"shutdown_initiated\"}");
    }

    private void initiateGracefulShutdown(String initiatorId) {
        if (shuttingDown.compareAndSet(false, true)) {
            shutdownInitiator.set(initiatorId);
            scheduler.schedule(() -> forceCloseAll(), GRACE_PERIOD_MS, TimeUnit.MILLISECONDS);
            notifyAllSessions("{\"event\": \"shutdown_pending\", \"grace_ms\": " + GRACE_PERIOD_MS + "}");
        }
    }

    private void notifyAllSessions(String message) {
        activeSessions.forEach((id, s) -> {
            try {
                if (s.isOpen()) s.getBasicRemote().sendText(message);
            } catch (IOException ignored) {}
        });
    }

    private void forceCloseAll() {
        activeSessions.forEach((id, s) -> {
            try {
                if (s.isOpen()) s.close(new CloseReason(CloseReason.CloseCodes.GOING_AWAY, "Shutdown complete"));
            } catch (IOException ignored) {}
        });
        activeSessions.clear();
    }

    @OnClose
    public void onClose(Session session, CloseReason reason) {
        activeSessions.remove(session.getId());
    }

    @OnError
    public void onError(Session session, Throwable throwable) {
        activeSessions.remove(session.getId());
    }

    static class IndexCommand {
        private String type;
        private String target;

        static IndexCommand parse(String msg) {
            try {
                String[] parts = msg.split(":", 2);
                if (parts.length != 2) return null;
                IndexCommand cmd = new IndexCommand();
                cmd.type = parts[0].trim().toLowerCase();
                cmd.target = parts[1].trim();
                if (cmd.type.length() > 20 || cmd.target.length() > 500) return null;
                return cmd;
            } catch (Exception e) {
                return null;
            }
        }

        String getType() { return type; }
        String getTarget() { return target; }
    }
}
